const mentors = $('Fetch Mentor Roster').all()
  .map(item => item.json)
  .filter(row => row && row.email);

const pairings = $input.all()
  .map(item => item.json)
  .filter(row => row && row.mentor_email);

const activeCounts = {};
for (const row of pairings) {
  if (String(row.status || '').trim().toLowerCase() !== 'active') continue;
  const key = String(row.mentor_email).trim().toLowerCase();
  activeCounts[key] = (activeCounts[key] || 0) + 1;
}

const joiner = $('New Joiner Intake Form').first().json;
const joinerName = String(joiner['Full Name'] || '').trim();
const joinerEmail = String(joiner['Work Email'] || '').trim();
const joinerCohort = String(joiner['Team or Cohort'] || '').trim();

const truthy = value => ['true', 'yes', 'y', '1'].includes(String(value || '').trim().toLowerCase());

const eligible = mentors
  .map(mentor => {
    const key = String(mentor.email).trim().toLowerCase();
    return {
      name: String(mentor.mentor_name || mentor.name || '').trim(),
      email: String(mentor.email).trim(),
      slackId: String(mentor.slack_member_id || '').trim(),
      cohort: String(mentor.cohort || '').trim(),
      capacity: Number(mentor.capacity) || 0,
      onLeave: truthy(mentor.on_leave),
      lastAssigned: String(mentor.last_assigned || '').trim(),
      active: activeCounts[key] || 0,
    };
  })
  .filter(mentor => !mentor.onLeave && mentor.active < mentor.capacity);

const rank = (a, b) => {
  if (a.active !== b.active) return a.active - b.active;
  return a.lastAssigned.localeCompare(b.lastAssigned);
};

const sameCohort = joinerCohort
  ? eligible.filter(mentor => mentor.cohort.toLowerCase() === joinerCohort.toLowerCase())
  : [];
const pool = sameCohort.length > 0 ? sameCohort : eligible;
const winner = pool.slice().sort(rank)[0] || null;

const base = {
  joiner_name: joinerName,
  joiner_email: joinerEmail,
  joiner_cohort: joinerCohort,
  assigned_at: new Date().toISOString(),
};

if (!winner) {
  return [{ json: { ...base, matched: false, status: 'waitlisted', mentor_name: '', mentor_email: '', mentor_slack_id: '', cohort_match: false } }];
}

return [{ json: { ...base, matched: true, status: 'active', mentor_name: winner.name, mentor_email: winner.email, mentor_slack_id: winner.slackId, cohort_match: sameCohort.length > 0 } }];
